@extends('layout') @section('title','Detail laporan') @section('content')<div class="heading"><div><div class="eyebrow">{{ config('k3.modules.'.$entry->module) }} &middot; #{{ $entry->id }}</div><h1>{{ $entry->title }}</h1><p>{{ $entry->area }} &middot; {{ $entry->date }} &middot; {{ $entry->reporter }}</p></div><div class="actions"><a class="button secondary" href="/module/{{ $entry->module }}"><x-icon name="back" size="16"/> Kembali</a>@if(\App\Http\Controllers\K3Controller::deletable($entry))<x-delete-button :action="'/entry/'.$entry->id" :message="'“'.$entry->title.'” beserta lampirannya akan dihapus permanen dari '.config('k3.modules.'.$entry->module).'. Tindakan ini tercatat di jejak audit dan tidak dapat dibatalkan.'"/>@endif</div></div><div class="grid equal"><section class="panel"><div class="panel-head"><h2>Informasi laporan</h2><span class="badge {{ $entry->status }}">{{ $entry->status }}</span></div><span class="badge">{{ $entry->category }}</span><div class="detail-text">{{ $entry->description }}</div>@if($entry->attachment)<p><a class="button secondary" href="/entry/{{ $entry->id }}/attachment"><x-icon name="download" size="16"/> Unduh lampiran</a></p>@endif @if($entry->checklist)@foreach($entry->checklist as $label=>$value)<div class="check-row"><span>{{ $label }}</span><span class="badge {{ $value }}">{{ $value }}</span></div>@endforeach @endif @if(App\Http\Controllers\K3Controller::writable($entry->module)&&(auth()->user()->role==='hse'||$entry->user_id===auth()->id()))<p><a class="text-link" href="/entry/{{ $entry->id }}/edit">Edit data <x-icon name="arrow" size="14"/></a></p>@endif</section><section class="panel"><h2>Tindak lanjut</h2><p class="detail-text">{{ $entry->resolution??'Belum ada catatan tindak lanjut.' }}</p>@if(in_array($entry->module,['reports','inspections'])&&in_array(auth()->user()->role,['hse','head']))<form action="/entry/{{ $entry->id }}/resolve" method="post">@csrf<div class="field"><label>Status penanganan</label><select name